// Minimal Client Component — only interactive leaf
'use client'
import { useState } from 'react'
export default function LikeButton({ likes }) {
  const [count, setCount] = useState(likes)
  return <button onClick={() => setCount(c => c + 1)}>{count}</button>
}

// Context provider as Client Component
'use client'
import { createContext, useState } from 'react'
export const ThemeContext = createContext({})
export default function ThemeProvider({ children }) {
  return <ThemeContext.Provider value="dark">{children}</ThemeContext.Provider>
}

// useSearchParams wrapped in Suspense (required)
import { Suspense } from 'react'
import SearchResults from './search-results' // 'use client' + useSearchParams
export default function Page() {
  return <Suspense fallback={<div>Loading...</div>}><SearchResults /></Suspense>
}

